CREATE OR REPLACE VIEW api.lo3rwang_keywords_manage AS
 SELECT uid,
    type,
    title AS name,
    description AS "desc",
    COALESCE(ARRAY( SELECT jsonb_array_elements_text(
                CASE
                    WHEN a.type = 'item'::text THEN COALESCE(a.attr -> 'keyword'::text, '[]'::jsonb)
                    ELSE COALESCE(a.attr -> 'uid'::text, '[]'::jsonb)
                END) AS jsonb_array_elements_text), ARRAY[]::text[]) AS lists,
        CASE
            WHEN type = ANY (ARRAY['group'::text, 'item'::text]) THEN jsonb_build_object('total', COALESCE((attr ->> 'total'::text)::integer, 0))
            ELSE '{}'::jsonb
        END AS uid_lists
   FROM silver.lo3rwang_anchor a
  WHERE (type = ANY (ARRAY['category'::text, 'class'::text, 'group'::text, 'item'::text])) AND ((coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) -> 'grants') ? 'global:manage' OR (coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) -> 'grants') ? 'lo3rwang:manage');
-- Preserve the repeated-label constraint without a PostgreSQL function.
ALTER TABLE api.manage DROP CONSTRAINT loc_domain_no_repeated_labels;
ALTER TABLE api.manage ADD CONSTRAINT loc_domain_no_repeated_labels
CHECK (domain IS NULL OR domain !~* '(^|\.)([a-z0-9-]+)(\.[a-z0-9-]+)*\.\2(\.|$)');
